using System;using System.Collections.Generic;using System.IO;using System.Net;using System.Security.Cryptography;using System.Text;using System.Web.Script.Serialization;using Microsoft.Win32;
namespace PipDesktop {
 // Public broker sees opaque topics and authenticated ciphertext, never names/codes.
 public class RelayCrypto {
  public static byte[] Hash(byte[] b){using(SHA256 h=SHA256.Create())return h.ComputeHash(b);}
  public static string Hex(byte[] b){return BitConverter.ToString(b).Replace("-","").ToLowerInvariant();}
  public static string NewSecret(){byte[] b=new byte[32];using(RandomNumberGenerator r=RandomNumberGenerator.Create())r.GetBytes(b);return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}
  public static byte[] Secret(string code){string[] a=code.Split('.');if(a.Length!=3||a[0]!="PIP1"||a[1].Length!=43||a[2].Length!=16)throw new InvalidDataException("Код друга не подходит");byte[] b=Convert.FromBase64String(a[1].Replace('-','+').Replace('_','/')+"=");if(b.Length!=32)throw new InvalidDataException();return b;}
  static byte[] Key(string code,string purpose){return Hash(Encoding.UTF8.GetBytes(Convert.ToBase64String(Secret(code))+purpose));}
  public static string Topic(string code){Secret(code);return "pip-v1-"+Hex(Hash(Encoding.UTF8.GetBytes(code))).Substring(0,40);}
  public static string Seal(string code,string plain){byte[] iv=new byte[16];using(RandomNumberGenerator r=RandomNumberGenerator.Create())r.GetBytes(iv);byte[] encrypted;using(Aes a=Aes.Create()){a.Key=Key(code,"enc");a.IV=iv;using(ICryptoTransform t=a.CreateEncryptor()){byte[] b=Encoding.UTF8.GetBytes(plain);encrypted=t.TransformFinalBlock(b,0,b.Length);}}byte[] bytes=new byte[iv.Length+encrypted.Length];Buffer.BlockCopy(iv,0,bytes,0,16);Buffer.BlockCopy(encrypted,0,bytes,16,encrypted.Length);byte[] mac;using(HMACSHA256 h=new HMACSHA256(Key(code,"mac")))mac=h.ComputeHash(bytes);return Convert.ToBase64String(bytes)+"."+Convert.ToBase64String(mac);}
  public static string Open(string code,string sealedText){string[] parts=sealedText.Split('.');if(parts.Length!=2||sealedText.Length>6000)throw new InvalidDataException();byte[] data=Convert.FromBase64String(parts[0]),tag=Convert.FromBase64String(parts[1]);byte[] mac;using(HMACSHA256 h=new HMACSHA256(Key(code,"mac")))mac=h.ComputeHash(data);int diff=tag.Length^mac.Length;for(int i=0;i<Math.Min(tag.Length,mac.Length);i++)diff|=tag[i]^mac[i];if(diff!=0||data.Length<32)throw new InvalidDataException();using(Aes a=Aes.Create()){a.Key=Key(code,"enc");byte[] iv=new byte[16];Buffer.BlockCopy(data,0,iv,0,16);a.IV=iv;using(ICryptoTransform t=a.CreateDecryptor())return Encoding.UTF8.GetString(t.TransformFinalBlock(data,16,data.Length-16));}}
 }
 public class RelayFriend {public string code,name,n;public bool accepted,incoming;public double seen;}
 public class RelayMessage {public string action,code,name,visit,nonce;public int accessory;public double time,expires;}
 public class RelayEnvelope {public string payload,sig,n;}
 public class RelaySaved {public string code,privateKey;public List<RelayFriend> friends=new List<RelayFriend>();public List<string> seen=new List<string>();public string budgetDay="";public int sent;}
 public class FriendsRelay {
  const string Host="https://ntfy.sh/";readonly string key;readonly JavaScriptSerializer json=new JavaScriptSerializer();RelaySaved saved;RSACryptoServiceProvider rsa;FriendVisit visit;double lastReceived,lastBeat;string peer;string petName="Пип";int accessory;
  public FriendsRelay(string registryKey){key=registryKey;using(RegistryKey k=Registry.CurrentUser.OpenSubKey(key)){if(k!=null)try{saved=json.Deserialize<RelaySaved>((string)k.GetValue("Relay",""));}catch{}}if(saved==null){rsa=new RSACryptoServiceProvider(2048);rsa.PersistKeyInCsp=false;saved=new RelaySaved{privateKey=rsa.ToXmlString(true)};saved.code="PIP1."+RelayCrypto.NewSecret()+"."+RelayCrypto.Hex(RelayCrypto.Hash(rsa.ExportParameters(false).Modulus)).Substring(0,16);Save();}else{rsa=new RSACryptoServiceProvider();rsa.PersistKeyInCsp=false;rsa.FromXmlString(saved.privateKey);}}
  public string Code{get{return saved.code;}}
  void Save(){using(RegistryKey k=Registry.CurrentUser.CreateSubKey(key))k.SetValue("Relay",json.Serialize(saved));}
  static double Now(){return (DateTime.UtcNow-new DateTime(1970,1,1)).TotalSeconds;}
  RelayFriend Find(string code){return saved.friends.Find(delegate(RelayFriend f){return f.code==code;});}
  public FriendState Perform(string route,Dictionary<string,object> p,string name,int acc){petName=name;accessory=acc;double now=Now();Expire(now);if(route=="/register")return Snapshot(now);Poll(now);
   string other=p!=null&&p.ContainsKey("friend")?(string)p["friend"]:"";RelayFriend f=Find(other);
   if(route=="/friend/request"){other=((string)p["code"]).Trim();RelayCrypto.Secret(other);if(other==saved.code)throw new Exception("Это твой собственный код");if(Find(other)!=null)throw new Exception("Друг уже в списке");if(saved.friends.Count>=30)throw new Exception("В списке уже 30 друзей");Send(other,"friend_request",null,now+86400);saved.friends.Add(new RelayFriend{code=other,name="Ожидаем друга",incoming=false,accepted=false});}
   else if(route=="/friend/accept"){if(f==null||!f.incoming||f.accepted)throw new Exception("Нет входящего запроса");Send(other,"friend_accept",null,now+86400);f.accepted=true;}
   else if(route=="/friend/remove"){if(f!=null){Send(other,"friend_remove",null,now+60);saved.friends.Remove(f);if(peer==other)visit=null;}}
   else if(route=="/visit/request"){if(f==null||!f.accepted)throw new Exception("Сначала подтвердите дружбу");if(visit!=null)throw new Exception("Визит уже существует");string id=Guid.NewGuid().ToString("N");Send(other,"offer",id,now+120);peer=other;visit=new FriendVisit{id=id,status="pending",outgoing=true,expires=now+120,pet=Pet(f,now)};}
   else if(route=="/visit/accept"){if(visit==null||visit.outgoing||visit.status!="pending")throw new Exception("Нет входящего визита");Send(peer,"accept",visit.id,now+180);visit.status="ready";visit.expires=now+180;lastReceived=now;}
   else if(route=="/visit/end"||route=="/disconnect"){if(visit!=null)Send(peer,"end",visit.id,now+60);visit=null;}
   if(visit!=null&&visit.status=="active"&&now-lastBeat>=20){Send(peer,"beat",visit.id,visit.expires);lastBeat=now;}Save();return Snapshot(now);
  }
  void Expire(double now){if(visit!=null&&(now>=visit.expires||(visit.status!="pending"&&now-lastReceived>45)))visit=null;}
  FriendPet Pet(RelayFriend f,double now){return new FriendPet{id=f.code,code=f.code,name=f.name,accepted=f.accepted,incoming=f.incoming,online=now-f.seen<60};}
  FriendState Snapshot(double now){Expire(now);List<FriendPet> friends=new List<FriendPet>();foreach(RelayFriend f in saved.friends)friends.Add(Pet(f,now));return new FriendState{code=saved.code,friends=friends.ToArray(),visits=visit==null?new FriendVisit[0]:new[]{visit}};}
  void Send(string destination,string action,string id,double expiry){string day=DateTime.UtcNow.ToString("yyyy-MM-dd");if(saved.budgetDay!=day){saved.budgetDay=day;saved.sent=0;}if(saved.sent>=190)throw new Exception("Сегодня лимит бесплатной связи исчерпан. Попробуй завтра.");RelayMessage m=new RelayMessage{action=action,code=saved.code,name=petName,accessory=accessory,visit=id,nonce=Guid.NewGuid().ToString("N"),time=Now(),expires=expiry};byte[] b=Encoding.UTF8.GetBytes(json.Serialize(m));RelayEnvelope envelope=new RelayEnvelope{payload=Convert.ToBase64String(b),sig=Convert.ToBase64String(rsa.SignData(b,"SHA256")),n=Convert.ToBase64String(rsa.ExportParameters(false).Modulus)};string body=RelayCrypto.Seal(destination,json.Serialize(envelope));using(WebClient c=new UpdateClient()){c.Encoding=Encoding.UTF8;c.Headers["Content-Type"]="text/plain";c.Headers["Priority"]="1";c.UploadString(Host+RelayCrypto.Topic(destination),"POST",body);}saved.sent++;Save();}
  void Poll(double now){string response;using(WebClient c=new UpdateClient()){c.Encoding=Encoding.UTF8;response=c.DownloadString(Host+RelayCrypto.Topic(saved.code)+"/json?poll=1&since=120s");}if(response.Length>262144)throw new IOException();foreach(string line in response.Split('\n')){if(line.Trim().Length==0)continue;try{Dictionary<string,object> outer=json.Deserialize<Dictionary<string,object>>(line);if(!outer.ContainsKey("message"))continue;RelayEnvelope e=json.Deserialize<RelayEnvelope>(RelayCrypto.Open(saved.code,(string)outer["message"]));byte[] b=Convert.FromBase64String(e.payload),mod=Convert.FromBase64String(e.n);if(mod.Length!=256)continue;RelayMessage m=json.Deserialize<RelayMessage>(Encoding.UTF8.GetString(b));RelayCrypto.Secret(m.code);if(m.code.Split('.')[2]!=RelayCrypto.Hex(RelayCrypto.Hash(mod)).Substring(0,16)||m.time>now+30||m.expires<now||now-m.time>120||m.nonce==null||saved.seen.Contains(m.nonce)||m.name==null||m.name.Length>24||m.accessory<0||m.accessory>5)continue;using(RSACryptoServiceProvider pub=new RSACryptoServiceProvider()){pub.PersistKeyInCsp=false;pub.ImportParameters(new RSAParameters{Modulus=mod,Exponent=new byte[]{1,0,1}});if(!pub.VerifyData(b,"SHA256",Convert.FromBase64String(e.sig)))continue;}RelayFriend f=Find(m.code);if(f!=null&&f.n!=null&&f.n!=e.n)continue;saved.seen.Add(m.nonce);if(saved.seen.Count>512)saved.seen.RemoveAt(0);Receive(m,e.n,now);}catch(FormatException){}catch(ArgumentException){}catch(InvalidDataException){}catch(CryptographicException){}catch(InvalidOperationException){}}Save();}
  void Receive(RelayMessage m,string n,double now){RelayFriend f=Find(m.code);if(m.action=="friend_request"){if(f==null&&saved.friends.Count<30)saved.friends.Add(new RelayFriend{code=m.code,name=m.name,n=n,incoming=true,seen=now});else if(f!=null&&!f.accepted){f.n=n;f.name=m.name;f.incoming=true;}return;}if(f==null)return;if(m.action=="friend_accept"){f.n=n;f.name=m.name;f.accepted=true;f.seen=now;return;}if(m.action=="friend_remove"){saved.friends.Remove(f);if(peer==m.code)visit=null;return;}if(!f.accepted)return;f.name=m.name;f.seen=now;
   if(m.action=="offer"){if(visit!=null)return;peer=m.code;visit=new FriendVisit{id=m.visit,status="pending",outgoing=false,expires=Math.Min(now+120,m.expires),pet=new FriendPet{name=m.name,accessory=m.accessory,id=m.code}};return;}
   if(visit==null||peer!=m.code||visit.id!=m.visit)return;
   if(m.action=="end"){visit=null;return;}if(m.action=="accept"&&visit.outgoing&&visit.status=="pending"){Send(peer,"start",visit.id,m.expires);visit.status="active";visit.expires=Math.Min(now+180,m.expires);lastReceived=lastBeat=now;return;}
   if(m.action=="start"&&!visit.outgoing&&visit.status=="ready"){visit.status="active";lastReceived=now;Send(peer,"beat",visit.id,visit.expires);lastBeat=now;return;}if(m.action=="beat"&&visit.status=="active")lastReceived=now;
  }
 }
}
